def calculate_L_b(task_set):
    w_current = sum(task.C for task in task_set)
    while True:
        w_previous = w_current
        w_next = 0
        for task_i in task_set:
            # ceil(w_previous / T_i) is equivalent to (w_previous + T_i - 1) // T_i for positive integers
            num_jobs = (w_previous + task_i.T - 1) // task_i.T
            w_next += num_jobs * task_i.C
        w_current = w_next
        if w_current == w_previous:
            break
    return w_current

def calculate_L_a(task_set):
    U = sum(task.C / task.T for task in task_set)
    if U >= 1:
        # Handle U=1 case separately, or indicate unschedulable if U > 1
        return float('inf') # Or a specific value like L_b for U=1

    max_D = 0
    max_T_U_term = 0
    for task_i in task_set:
        if task_i.D > max_D:
            max_D = task_i.D
        term = task_i.T * U / (1 - U)
        if term > max_T_U_term:
            max_T_U_term = term

    L_a = max(max_D, max_T_U_term)
    return L_a

def calculate_L_a_star(task_set):
    U = sum(task.C / task.T for task in task_set)
    if U >= 1:
        return float('inf')

    max_D = 0
    max_T_U_term_star = 0
    for task_i in task_set:
        if task_i.D > max_D:
            max_D = task_i.D
        term_star = (task_i.T * U / (1 - U)) - task_i.T + task_i.D
        if term_star > max_T_U_term_star:
            max_T_U_term_star = term_star

    L_a_star = max(max_D, max_T_U_term_star)
    return L_a_star

def calculate_L_qpa(task_set):
    U = sum(task.C / task.T for task in task_set)
    L_b = calculate_L_b(task_set)
    if U == 1:
        return L_b
    else:
        L_a_star = calculate_L_a_star(task_set)
        return min(L_a_star, L_b)

def find_largest_failing_deadline(L, task_set):
    delta_d = -1 # Initialize with a value smaller than any possible deadline
    # This would typically iterate over a set of candidate deadlines P_a
    # For simplicity, let's assume we can iterate over all relevant deadlines
    candidate_deadlines = generate_all_absolute_deadlines_up_to_L(task_set, L)

    for d in sorted(candidate_deadlines):
        if d <= 0 or d >= L:
            continue
        h_d = calculate_processor_demand(d, task_set)
        if h_d > d:
            delta_d = d
    return delta_d

def find_closest_deadline(delta_d, task_set, L):
    all_deadlines = generate_all_absolute_deadlines_up_to_L(task_set, L)
    d_prime = float('inf')
    for d in all_deadlines:
        if d > delta_d and d < d_prime:
            d_prime = d
    return d_prime

