def find_largest_failing_deadline_in_subinterval(x_L, task_set):
    lambda_d = -1
    candidate_deadlines = generate_all_absolute_deadlines_up_to_L(task_set, x_L)
    for d in sorted(candidate_deadlines):
        if d <= 0 or d >= x_L:
            continue
        h_d = calculate_processor_demand(d, task_set)
        if h_d > d:
            lambda_d = d
    return lambda_d

def find_largest_failing_deadline_in_remaining_interval(x_L, L, task_set):
    gamma_d = -1
    candidate_deadlines = generate_all_absolute_deadlines_up_to_L(task_set, L)
    for d in sorted(candidate_deadlines):
        if d < x_L or d >= L:
            continue
        h_d = calculate_processor_demand(d, task_set)
        if h_d > d:
            gamma_d = d
    return gamma_d

def check_schedulability_lemma2(task_set, L_bound):
    # L_bound would be min(L_a_star, L_b) or L_qpa
    candidate_deadlines = generate_all_absolute_deadlines_up_to_L(task_set, L_bound)
    for d in sorted(candidate_deadlines):
        h_d = calculate_processor_demand(d, task_set)
        if h_d > d:
            return False # Unschedulable
    return True # Schedulable (assuming U <= 1 is also checked)

def theorem3_schedulability_test(task_set):
    U = sum(task.C / task.T for task in task_set)
    if U > 1:
        return False # Unschedulable due to overload

    L_b = calculate_L_b(task_set)

    # As per Lemma 2, only need to check at absolute deadlines
    candidate_deadlines = generate_all_absolute_deadlines_up_to_L(task_set, L_b)
    for t in sorted(candidate_deadlines):
        h_t = calculate_processor_demand(t, task_set)
        if h_t > t:
            return False # Unschedulable due to demand exceeding time

    return True # Schedulable
